12hj|function addNoise(ctx, w, h, amount = 8) {
13ry|  const imageData = ctx.getImageData(0, 0, w, h);
14rd|  const d = imageData.data;
15vi|  for (let i = 0; i < d.length; i += 4) {
16sl|    const offset = (Math.random() - 0.5) * amount;
17rb|    d[i] = Math.max(0, Math.min(255, d[i] + offset));
18wg|    d[i + 1] = Math.max(0, Math.min(255, d[i + 1] + offset));
19kb|    d[i + 2] = Math.max(0, Math.min(255, d[i + 2] + offset));
20iq|  }
21wr|  ctx.putImageData(imageData, 0, 0);
