72zy|  update(delta) {
73ax|    if (!this.isLocked) return;
74yy|
75cl|    // Friction
76wj|    this.velocity.x *= 1 - 10 * delta;
77pd|    this.velocity.z *= 1 - 10 * delta;
78yy|
79oa|    // Acceleration from input
80rl|    this.direction.z = Number(this.moveForward) - Number(this.moveBackward);
81ii|    this.direction.x = Number(this.moveRight) - Number(this.moveLeft);
82en|    this.direction.normalize();
83yy|
84ol|    const accel = this.moveSpeed * 20 * delta;
85ym|    this.velocity.z -= this.direction.z * accel;
86li|    this.velocity.x -= this.direction.x * accel;
87yy|
88wf|    // Move relative to camera yaw
89zs|    const forward = new THREE.Vector3();
90xi|    this.camera.getWorldDirection(forward);
91mr|    forward.y = 0;
92sj|    forward.normalize();
93yy|
94af|    const right = new THREE.Vector3();
95wr|    right.crossVectors(forward, new THREE.Vector3(0, 1, 0)).normalize();
