101zi|    const margin = 0.25;
102sn|    for (const wall of this.walls) {
103at|      const px = this.camera.position.x;
104tr|      const pz = this.camera.position.z;
105yy|
106pf|      // Vector from wall start to end
107zm|      const dx = wall.x2 - wall.x1;
108gh|      const dz = wall.z2 - wall.z1;
109oe|      const lenSq = dx * dx + dz * dz;
110mt|      if (lenSq === 0) continue;
111yy|
112rd|      // Project player onto wall segment (clamped to [0,1])
113bl|      let t = ((px - wall.x1) * dx + (pz - wall.z1) * dz) / lenSq;
114ex|      t = Math.max(0, Math.min(1, t));
115yy|
116ha|      // Closest point on segment
117cf|      const cx = wall.x1 + t * dx;
118uw|      const cz = wall.z1 + t * dz;
119yy|
120th|      // Distance from player to closest point
121mf|      const ox = px - cx;
122xy|      const oz = pz - cz;
123wa|      const dist = Math.sqrt(ox * ox + oz * oz);
124yy|
125iw|      if (dist < margin && dist > 0.0001) {
126ts|        // Push player out along normal
127qt|        const pushX = (ox / dist) * (margin - dist);
128ok|        const pushZ = (oz / dist) * (margin - dist);
129zh|        this.camera.position.x += pushX;
130eh|        this.camera.position.z += pushZ;
131ej|      }
132sp|    }
133yy|
134np|    // Lock to eye height
135aj|    this.camera.position.y = 1.6;
